6	const DIVERSITY_THRESHOLD = 3;
7	const POINTS_PER_SPHINX = 1;
8	const POINTS_PER_SPHINX_WHEN_DIVERSE = 2;
9	
10	const countSphinxes = (army: Card[]): number =>
11	  army.filter((card) => card.monster === "sphinx").length;
12	
13	const countDistinctTypes = (army: Card[]): number =>
14	  new Set(army.map((card) => `${card.monster}-${card.rank}`)).size;
15	
16	export const scoreArmy = (army: Card[]): number => {
17	  const isDiverse = countDistinctTypes(army) > DIVERSITY_THRESHOLD;
18	  const pointsPerSphinx = isDiverse ? POINTS_PER_SPHINX_WHEN_DIVERSE : POINTS_PER_SPHINX;
19	  return countSphinxes(army) * pointsPerSphinx;
20	};
